{
 "summary": "The theorem says: for every a.e.-strongly-measurable f : ℝ/2πℤ → ℂ with ∫ |f| log(2+|f|) dμ < ∞, where μ is normalized Haar measure, there is a measurable null set E off which the symmetric Fourier partial sums S_N f(x) = Σ_{|k|≤N} f̂(k) e^{ikx} converge to f(x) as N → ∞ along all N. This matches Theorem 1.1 faithfully. The integrability hypothesis implies f ∈ L¹, so `fourierCoeff` is not a junk value. No significant caveat was found; only the auxiliary weak-L¹ maximal corollary is left unformalized.",
 "glossary": [
  {"decl": "circlePeriod_pos", "line": 8, "plain": "Instance recording 0 < 2π, needed to use AddCircle (2π) and its Haar probability measure.", "standard_concept": "positivity of the circle period", "matches_standard": "yes", "note": ""},
  {"decl": "AddCircle.haarAddCircle", "line": 13, "plain": "Normalized (probability) Haar measure on T = ℝ/2πℤ, i.e. dx/2π.", "standard_concept": "normalized Lebesgue measure μ on T", "matches_standard": "yes", "note": "Null sets agree with those of Lebesgue measure, and the normalization matches the standard Fourier coefficient convention."},
  {"decl": "fourierCoeff", "line": 20, "plain": "f̂(k) = ∫_T e^{-ikx} f(x) dμ(x).", "standard_concept": "Fourier coefficient", "matches_standard": "yes", "note": "Would be junk 0 if the integrand were not integrable, but f ∈ L¹ follows from the hypothesis."},
  {"decl": "fourier", "line": 20, "plain": "Character x ↦ e^{ikx} on ℝ/2πℤ.", "standard_concept": "trigonometric character", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "paperMain", "line": 12, "plain": "For all f : ℝ/2πℤ → ℂ that are a.e.-strongly measurable with x ↦ |f(x)| log(2+|f(x)|) integrable for normalized Haar measure μ, there exists a measurable E with μ(E) = 0 such that for every x ∉ E, Σ_{k=-N}^{N} f̂(k) e^{ikx} → f(x) as N → ∞ (N ∈ ℕ)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every complex-valued f ∈ L log L(T), i.e. ∫ |f| log(2+|f|) dμ < ∞, there is a measurable null set N_f with lim_{N→∞} S_N f(x) = f(x) for x ∈ T \\ N_f, along the full sequence N = 0, 1, 2, …"},
